{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"private_outputs":true,"provenance":[],"authorship_tag":"ABX9TyNJp/DiiQDhx9Fm1C1qoi+u"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"jgIESEqb0FIj"},"outputs":[],"source":["import requests\n","import json\n","import os\n","import time\n","from datetime import datetime\n","\n","# 1.Setup and Variables\n","BASE_URL = \"https://hacker-news.firebaseio.com/v0\"\n","HEADERS = {\"User-Agent\": \"TrendPulse/1.0\"}\n","\n","# Categories and Keywords\n","CATEGORIES = {\n","    \"technology\": [\"AI\", \"software\", \"tech\", \"code\", \"computer\", \"data\", \"cloud\", \"API\", \"GPU\", \"LLM\"],\n","    \"worldnews\": [\"war\", \"government\", \"country\", \"president\", \"election\", \"climate\", \"attack\", \"global\"],\n","    \"sports\": [\"NFL\", \"NBA\", \"FIFA\", \"sport\", \"game\", \"team\", \"player\", \"league\", \"championship\"],\n","    \"science\": [\"research\", \"study\", \"space\", \"physics\", \"biology\", \"discovery\", \"NASA\", \"genome\"],\n","    \"entertainment\": [\"movie\", \"film\", \"music\", \"Netflix\", \"game\", \"book\", \"show\", \"award\", \"streaming\"]\n","}\n","\n","collected_data = []\n","category_counts = {cat: 0 for cat in CATEGORIES}\n","\n","def get_category(title):\n","    title_lower = title.lower()\n","    for category, keywords in CATEGORIES.items():\n","        for word in keywords:\n","            if word.lower() in title_lower:\n","                return category\n","    return None\n","\n","# folder creation\n","if not os.path.exists('data'):\n","    os.makedirs('data')\n","\n","try:\n","    # Step 1:Fetching Top Story IDs\n","    print(\"Fetching top stories...\")\n","    response = requests.get(f\"{BASE_URL}/topstories.json\", headers=HEADERS)\n","    story_ids = response.json()[:500]\n","\n","    # Step 2: Fetching each story's details\n","    for cat_name in CATEGORIES.keys():\n","        print(f\"Processing category: {cat_name}...\")\n","\n","        for s_id in story_ids:\n","            # A maximum of 25 stories per category only\n","            if category_counts[cat_name] >= 25:\n","                break\n","\n","            try:\n","                item_res = requests.get(f\"{BASE_URL}/item/{s_id}.json\", headers=HEADERS)\n","                story = item_res.json()\n","\n","                if not story or 'title' not in story:\n","                    continue\n","\n","                assigned_cat = get_category(story['title'])\n","\n","                # Saving the data if the story category matches\n","                if assigned_cat == cat_name:\n","                    story_info = {\n","                        \"post_id\": story.get(\"id\"),\n","                        \"title\": story.get(\"title\"),\n","                        \"category\": assigned_cat,\n","                        \"score\": story.get(\"score\"),\n","                        \"num_comments\": story.get(\"descendants\", 0),\n","                        \"author\": story.get(\"by\"),\n","                        \"collected_at\": datetime.now().strftime(\"%Y-%m-%d %H:%M:%S\")\n","                    }\n","                    collected_data.append(story_info)\n","                    category_counts[cat_name] += 1\n","\n","            except Exception as e:\n","                print(f\"Error fetching story {s_id}: {e}\")\n","                continue\n","\n","        # A 2-second pause after the category loop ends\n","        time.sleep(2)\n","\n","    # 3.Saving to a JSON file\n","    date_str = datetime.now().strftime(\"%Y%m%d\")\n","    file_path = f\"data/trends_{date_str}.json\"\n","\n","    with open(file_path, 'w') as f:\n","        json.dump(collected_data, f, indent=4)\n","\n","    print(f\"Collected {len(collected_data)} stories. Saved to {file_path}\")\n","\n","except Exception as e:\n","    print(f\"An error occurred: {e}\")"]},{"cell_type":"code","source":["import pandas as pd\n","import os\n","from datetime import datetime\n","\n","# 1.Load the JSON File\n","# You need to change it here based on your file name\n","date_str = datetime.now().strftime(\"%Y%m%d\")\n","input_file = f\"data/trends_{date_str}.json\"\n","output_file = \"data/trends_clean.csv\"\n","\n","try:\n","    if not os.path.exists(input_file):\n","        print(f\"Error: {input_file} ఫైల్ దొరకలేదు!\")\n","    else:\n","        # JSON load\n","        df = pd.read_json(input_file)\n","        print(f\"Loaded {len(df)} stories from {input_file}\")\n","\n","        # 2. Clean the Data\n","\n","        # Remove Duplicates\n","        df = df.drop_duplicates(subset=['post_id'])\n","        print(f\"After removing duplicates: {len(df)}\")\n","\n","        # Remove Nulls\n","        df = df.dropna(subset=['post_id', 'title', 'score'])\n","        print(f\"After removing nulls: {len(df)}\")\n","\n","        # Fix Data Types\n","        df['score'] = df['score'].astype(int)\n","        df['num_comments'] = df['num_comments'].fillna(0).astype(int)\n","\n","        # Low Quality Filter\n","        df = df[df['score'] >= 5]\n","        print(f\"After removing low scores: {len(df)}\")\n","\n","        # Whitespace\n","        df['title'] = df['title'].str.strip()\n","\n","        # 3. Save as CSV\n","        df.to_csv(output_file, index=False)\n","        print(f\"Saved {len(df)} rows to {output_file}\")\n","\n","        # Summary\n","        print(\"\\nStories per category:\")\n","        print(df['category'].value_counts())\n","\n","except Exception as e:\n","    print(f\"An error occurred: {e}\")"],"metadata":{"id":"afe8uoHB0moQ"},"execution_count":null,"outputs":[]},{"cell_type":"code","source":["import pandas as pd\n","import numpy as np\n","\n","# 1. Load and Explore\n","try:\n","    file_path = \"data/trends_clean.csv\"\n","    df = pd.read_json(file_path) if file_path.endswith('.json') else pd.read_csv(file_path)\n","\n","    print(f\"Loaded data: {df.shape}\")\n","    print(\"\\nFirst 5 rows:\")\n","    print(df.head())\n","\n","    # Average score and comments\n","    avg_score = df['score'].mean()\n","    avg_comments = df['num_comments'].mean()\n","    print(f\"\\nAverage score   : {avg_score:.2f}\")\n","    print(f\"Average comments: {avg_comments:.2f}\")\n","\n","    # 2. Basic Analysis with NumPy\n","    print(\"\\n--- NumPy Stats ---\")\n","\n","    scores = df['score'].to_numpy()\n","\n","    print(f\"Mean score   : {np.mean(scores):.2f}\")\n","    print(f\"Median score : {np.median(scores):.2f}\")\n","    print(f\"Std deviation: {np.std(scores):.2f}\")\n","    print(f\"Max score    : {np.max(scores)}\")\n","    print(f\"Min score    : {np.min(scores)}\")\n","\n","    # Which category has the most stories?\n","    top_category = df['category'].value_counts().idxmax()\n","    cat_count = df['category'].value_counts().max()\n","    print(f\"Most stories in: {top_category} ({cat_count} stories)\")\n","\n","    # The story with the most comments\n","    max_comments_idx = df['num_comments'].idxmax()\n","    top_story = df.loc[max_comments_idx]\n","    print(f\"Most commented story: \\\"{top_story['title']}\\\" — {top_story['num_comments']} comments\")\n","\n","    # 3. Add New Columns\n","\n","    # Engagement: Division by zero రాకుండా score + 1\n","    df['engagement'] = df['num_comments'] / (df['score'] + 1)\n","\n","    # Is Popular: True if higher than the average score, else False\n","    df['is_popular'] = df['score'] > avg_score\n","\n","    # 4. Save the Result\n","    output_file = \"data/trends_analysed.csv\"\n","    df.to_csv(output_file, index=False)\n","    print(f\"\\nSaved to {output_file}\")\n","\n","except FileNotFoundError:\n","    print(\"Error: 'data/trends_clean.csv' file missing. fist Task 2 completed.\")\n","except Exception as e:\n","    print(f\"An error occurred: {e}\")"],"metadata":{"id":"-lLm-e2109zm"},"execution_count":null,"outputs":[]},{"cell_type":"code","source":["import pandas as pd\n","import matplotlib.pyplot as plt\n","import os\n","\n","# 1. Setup\n","try:\n","    # Load the data from Task 3\n","    df = pd.read_csv(\"data/trends_analysed.csv\")\n","\n","    # Create outputs folder if it doesn't exist\n","    if not os.path.exists('outputs'):\n","        os.makedirs('outputs')\n","\n","    # 2. Chart 1: Top 10 Stories by Score (Horizontal Bar Chart)\n","    plt.figure(figsize=(10, 6))\n","    top_10 = df.nlargest(10, 'score')\n","\n","    # Shorten titles longer than 50 characters\n","    titles = [t[:47] + \"...\" if len(t) > 50 else t for t in top_10['title']]\n","\n","    plt.barh(titles, top_10['score'], color='skyblue')\n","    plt.xlabel('Score')\n","    plt.title('Top 10 Stories by HackerNews Score')\n","    plt.gca().invert_yaxis() # Highest score at the top\n","    plt.tight_layout()\n","    plt.savefig('outputs/chart1_top_stories.png')\n","    plt.close()\n","\n","    # 3. Chart 2: Stories per Category (Bar Chart)\n","    plt.figure(figsize=(10, 6))\n","    category_counts = df['category'].value_counts()\n","    colors = ['red', 'green', 'blue', 'orange', 'purple']\n","\n","    category_counts.plot(kind='bar', color=colors[:len(category_counts)])\n","    plt.title('Distribution of Stories per Category')\n","    plt.xlabel('Category')\n","    plt.ylabel('Number of Stories')\n","    plt.xticks(rotation=45)\n","    plt.tight_layout()\n","    plt.savefig('outputs/chart2_categories.png')\n","    plt.close()\n","\n","    # 4. Chart 3: Score vs Comments (Scatter Plot)\n","    plt.figure(figsize=(10, 6))\n","    # Scatter plot with different colors for popular vs non-popular\n","    for popular_status, group in df.groupby('is_popular'):\n","        label = \"Popular\" if popular_status else \"Not Popular\"\n","        plt.scatter(group['score'], group['num_comments'], label=label, alpha=0.6)\n","\n","    plt.title('Correlation: Score vs Number of Comments')\n","    plt.xlabel('Score')\n","    plt.ylabel('Number of Comments')\n","    plt.legend()\n","    plt.grid(True, linestyle='--', alpha=0.5)\n","    plt.tight_layout()\n","    plt.savefig('outputs/chart3_scatter.png')\n","    plt.close()\n","\n","    # BONUS: Dashboard (Combined Figure)\n","    fig, axs = plt.subplots(2, 2, figsize=(15, 12))\n","    fig.suptitle('TrendPulse Dashboard', fontsize=20, fontweight='bold')\n","\n","    # Top Left: Categories\n","    category_counts.plot(kind='bar', ax=axs[0, 0], color=colors[:len(category_counts)])\n","    axs[0, 0].set_title('Stories per Category')\n","\n","    # Top Right: Scatter Plot\n","    for popular_status, group in df.groupby('is_popular'):\n","        label = \"Popular\" if popular_status else \"Not Popular\"\n","        axs[0, 1].scatter(group['score'], group['num_comments'], label=label, alpha=0.5)\n","    axs[0, 1].set_title('Score vs Comments')\n","    axs[0, 1].legend()\n","\n","    # Bottom: Top Stories (spanning across columns)\n","    # We delete the empty 4th subplot and make the 3rd one larger\n","    fig.delaxes(axs[1, 1])\n","    ax_bottom = plt.subplot(2, 1, 2)\n","    ax_bottom.barh(titles[:5], top_10['score'][:5], color='salmon') # Showing top 5 for space\n","    ax_bottom.set_title('Top 5 Trending Stories')\n","    ax_bottom.invert_yaxis()\n","\n","    plt.tight_layout(rect=[0, 0.03, 1, 0.95])\n","    plt.savefig('outputs/dashboard.png')\n","\n","    print(\"Visualizations complete! Check the 'outputs/' folder.\")\n","\n","except Exception as e:\n","    print(f\"An error occurred: {e}\")"],"metadata":{"id":"KVKsdZh70_z3"},"execution_count":null,"outputs":[]}]}